const logTypes = ['oak_log', 'birch_log', 'acacia_log', 'jungle_log', 'spruce_log', 'dark_oak_log', 'mangrove_log', 'cherry_log'];
let found = [];
for (const log of logTypes) {
  const blocks = await api.findBlocks(log, 64, 5);
  if (blocks && blocks.length > 0) {
    found = blocks;
    break;
  }
}
if (found.length > 0) {
  await api.goto(found[0].x, found[0].y, found[0].z, 2);
  await api.mine(['oak_log', 'birch_log', 'acacia_log', 'dark_oak_log'], 4);
} else {
  await api.wander(60);
}
return `Found ${found.length} logs`;
